		return nil, errors.New("all dimensions must be positive")
	}
	return &Cuboid{Length: length, Width: width, Height: height}, nil
}

// LateralSurfaceArea calculates the lateral surface area of the cuboid.
func (c *Cuboid) LateralSurfaceArea() (float64, error) {
